  Proof.
    intros QN QC ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc m mo h LB LF n lo d
      HOK HM0 HK0 HJ0 ST STKLO' SPL SPTOP SPA MI TP A0 NB BUD CH0 HFR XC24 FP CINIT HFRESH A0n B0n HA HB.
    pose proof (uwc_nonneg _ _ _ _ _ _ _ CH0) as D0.
    (* [comment removed for export] *)
    dpose HOK as (EL & _ & _).
    dpose HM0 as ((AWF & HLB) & GM & (GRO & GRW) & GT & GD & GC & GR & GQ & GS & GF & GI & GEMB).
    assert (XC' : c24_hid (win24 n = true -> cnt24 (AModel.blocks h) < C24MAX)) by (unfold c24_hid; rewrite <- HLB; exact XC24).   (* [comment removed for export] *)
    dpose AWF as ([WL WLS] & WC & WR & WK & WQ & WS & WD & WB & WBIG & WX & WG).
    set (L := h_L h) in *. set (T := l_T L) in *. set (CTX := l_ctx L) in *. set (SB := l_sb L) in *.
    set (SP := bv_unsigned sp) in *.
    assert (ESP : sp = Z_to_bv 64 SP) by (subst SP; symmetry; apply Z_to_bv_bv_unsigned).
    pose proof WL as WL'. unfold wf_L in WL'. fold L in WL'.
    aceilb.
    (* [comment removed for export] *)
    pose proof FP as FP'. unfold from_primary, kMaxSize in FP'. apply Z.leb_le in FP'.
    assert (N2E : needed2 n = needed n) by (unfold needed2; rewrite FP; reflexivity).
    assert (NDB : 24 <= needed n <= 0x10000).
    { unfold needed, rounded, round_up in FP' |- *. pose proof (rz_size_bound n). pose proof (Z.div_mod (Z.max n 8 + 8 - 1) 8 ltac:(clear; lia)).
      pose proof (Z.mod_pos_bound (Z.max n 8 + 8 - 1) 8 ltac:(clear; lia)). clear - H H0 H1 NB FP'. lia. }
    set (c := class_of (needed2 n)).
